{
  "name": "markdown-for-humans",
  "displayName": "Markdown for Humans: WYSIWYG Editor",
  "description": "A full-featured WYSIWYG Markdown editor with visual table editing, drag-and-drop images, Mermaid diagrams, and distraction-free writing—all inside VS Code.",
  "version": "0.2.1",
  "publisher": "concretio",
  "author": {
    "name": "Abhinav",
    "email": "abhinav@concret.io"
  },
  "license": "MIT",
  "icon": "icon.png",
  "galleryBanner": {
    "color": "#1e1e1e",
    "theme": "dark"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/concretios/markdown-for-humans"
  },
  "bugs": {
    "url": "https://github.com/concretios/markdown-for-humans/issues"
  },
  "homepage": "https://github.com/concretios/markdown-for-humans#readme",
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other",
    "Programming Languages"
  ],
  "keywords": [
    "markdown",
    "editor",
    "wysiwyg",
    "preview",
    "visual",
    "md",
    "table",
    "tables",
    "mermaid",
    "diagram",
    "image",
    "drag-drop",
    "github-flavored-markdown",
    "gfm",
    "notion-like",
    "writing",
    "documentation",
    "readme",
    "formatting",
    "syntax-highlighting",
    "live-preview",
    "full-screen",
    "distraction-free",
    "cover-images",
    "image-resizing",
    "export",
    "html",
    "pdf",
    "docx",
    "human-friendly"
  ],
  "main": "./dist/extension.js",
  "contributes": {
    "customEditors": [
      {
        "viewType": "markdownForHumans.editor",
        "displayName": "Markdown for Humans",
        "selector": [
          {
            "filenamePattern": "*.md",
            "scheme": "file"
          },
          {
            "filenamePattern": "*.markdown",
            "scheme": "file"
          },
          {
            "filenamePattern": "*.md",
            "scheme": "untitled"
          },
          {
            "filenamePattern": "*.markdown",
            "scheme": "untitled"
          }
        ],
        "priority": "option"
      }
    ],
    "commands": [
      {
        "command": "markdownForHumans.openFile",
        "title": "Open with Markdown for Humans"
      },
      {
        "command": "markdownForHumans.outline.revealCurrent",
        "title": "Outline: Reveal Current Heading",
        "icon": "$(target)"
      },
      {
        "command": "markdownForHumans.outline.filter",
        "title": "Outline: Filter Headings",
        "icon": "$(search)"
      },
      {
        "command": "markdownForHumans.outline.clearFilter",
        "title": "Outline: Clear Filter",
        "icon": "$(close)"
      },
      {
        "command": "markdownForHumans.copyAiContextRef",
        "title": "Markdown for Humans: Copy AI Context Reference (@file#lines)"
      }
    ],
    "keybindings": [
      {
        "command": "markdownForHumans.copyAiContextRef",
        "key": "alt+c",
        "mac": "alt+c",
        "when": "activeCustomEditorId == 'markdownForHumans.editor'"
      }
    ],
    "views": {
      "explorer": [
        {
          "id": "markdownForHumansOutline",
          "name": "Markdown for Humans: Outline",
          "when": "markdownForHumans.isActive"
        }
      ]
    },
    "menus": {
      "explorer/context": [
        {
          "command": "markdownForHumans.openFile",
          "when": "resourceExtname == .md",
          "group": "navigation"
        }
      ],
      "editor/title/context": [
        {
          "command": "markdownForHumans.openFile",
          "when": "resourceExtname == .md && activeCustomEditorId != 'markdownForHumans.editor'",
          "group": "navigation"
        }
      ],
      "view/title": [
        {
          "command": "markdownForHumans.outline.revealCurrent",
          "when": "view == markdownForHumansOutline",
          "group": "navigation@1"
        },
        {
          "command": "markdownForHumans.outline.filter",
          "when": "view == markdownForHumansOutline && !markdownForHumans.outlineFilterActive",
          "group": "navigation@2"
        },
        {
          "command": "markdownForHumans.outline.clearFilter",
          "when": "view == markdownForHumansOutline && markdownForHumans.outlineFilterActive",
          "group": "navigation@2"
        }
      ]
    },
    "configuration": {
      "title": "Markdown for Humans",
      "properties": {
        "markdownForHumans.imagePath": {
          "type": "string",
          "default": "images",
          "description": "Folder path for saved images. Interpreted relative to markdownForHumans.imagePathBase."
        },
        "markdownForHumans.imagePathBase": {
          "type": "string",
          "enum": [
            "relativeToDocument",
            "workspaceFolder"
          ],
          "default": "relativeToDocument",
          "description": "Controls whether Image Path is relative to the current markdown file folder or the workspace folder."
        },
        "markdownForHumans.chromePath": {
          "type": "string",
          "default": "",
          "markdownDescription": "Path to Google Chrome or Chromium executable for PDF export. Leave empty to auto-detect.\n\n**Download Chrome:**\n- [Windows/Mac/Linux](https://www.google.com/chrome/)\n- [Chromium (open source)](https://www.chromium.org/getting-involved/download-chromium/)\n\n**Common paths:**\n- **Mac:** `/Applications/Google Chrome.app/Contents/MacOS/Google Chrome`\n- **Windows:** `C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe`\n- **Linux:** `/usr/bin/google-chrome` or `/usr/bin/chromium`"
        },
        "markdownForHumans.imageResize.skipWarning": {
          "type": "boolean",
          "default": false,
          "description": "Skip the warning dialog when resizing images. When enabled, images will be resized immediately without confirmation."
        },
        "markdownForHumans.copyAiContextRef.skipSaveWarning": {
          "type": "boolean",
          "default": false,
          "description": "Skip the warning dialog when 'Copy AI Context Reference' needs to save the file first. When enabled, the document is saved silently before copying the reference."
        },
        "markdownForHumans.blankLines.mode": {
          "type": "string",
          "enum": [
            "preserve",
            "strip"
          ],
          "default": "strip",
          "description": "Controls whether extra blank lines are preserved or removed in the editor and saved file."
        },
        "markdownForHumans.imagePreview.hover.enabled": {
          "type": "boolean",
          "default": true,
          "description": "Enable the image hover overlay that shades images and displays metadata (resolution, file size, etc.) on hover.",
          "scope": "application"
        },
        "markdownForHumans.paragraph.spacingBefore": {
          "type": "number",
          "default": 0,
          "minimum": 0,
          "maximum": 72,
          "description": "Space before paragraphs in points (margin-top). Default: 0pt",
          "scope": "application"
        },
        "markdownForHumans.paragraph.spacingAfter": {
          "type": "number",
          "default": 0,
          "minimum": 0,
          "maximum": 72,
          "description": "Space after paragraphs in points (margin-bottom). Default: 0pt",
          "scope": "application"
        },
        "markdownForHumans.zoom": {
          "type": "number",
          "default": 100,
          "minimum": 50,
          "maximum": 200,
          "description": "Zoom level for the editor as a percentage. 100 = default size, 150 = 50% larger, etc.",
          "scope": "application"
        },
        "markdownForHumans.display.editorTheme": {
          "type": "string",
          "enum": [
            "vscode",
            "defaultLight",
            "defaultDark"
          ],
          "enumDescriptions": [
            "Follow VS Code theme",
            "Always use a light theme",
            "Always use a dark theme"
          ],
          "default": "vscode",
          "description": "Controls the editor's color theme. 'Follow VS Code theme' mirrors your active VS Code theme. 'Always light'/'Always dark' keep the editor light or dark regardless of VS Code: when VS Code's theme already matches that appearance the editor uses your real theme, otherwise it falls back to a built-in light/dark theme. The toolbar toggle switches between light and dark and applies to all open editors.",
          "scope": "application"
        },
        "markdownForHumans.display.documentWidth": {
          "type": "string",
          "enum": [
            "standard",
            "wide",
            "full"
          ],
          "enumDescriptions": [
            "Standard - a comfortable centered reading column",
            "Wide - a wider centered column",
            "100% - fill the editor width"
          ],
          "default": "standard",
          "markdownDescription": "Controls the editor content width. **Standard** and **Wide** center the content at a fixed measure; **100%** fills the available width (within the editor padding). Applies to both the live and code views.",
          "scope": "application"
        },
        "markdownForHumans.codeView.autoFormat": {
          "type": "boolean",
          "default": false,
          "markdownDescription": "When enabled, the code view's **Auto-format** checkbox starts on: the markdown source is tidied (table alignment, bullet/heading normalization, blank-line collapsing) when you enter the code view. Override it per document with the checkbox."
        },
        "markdownForHumans.outline.display": {
          "type": "string",
          "enum": [
            "overlay",
            "sidebar"
          ],
          "enumDescriptions": [
            "Show the outline as a modal overlay",
            "Dock the outline as a sidebar beside the content"
          ],
          "default": "overlay",
          "description": "How the document outline is shown when toggled from the toolbar."
        },
        "markdownForHumans.outline.sidebar.side": {
          "type": "string",
          "enum": [
            "left",
            "right"
          ],
          "default": "right",
          "description": "Which side the outline sidebar docks on (sidebar mode)."
        },
        "markdownForHumans.outline.sidebar.defaultLevel": {
          "type": "string",
          "enum": [
            "all",
            "h2",
            "h3",
            "h4"
          ],
          "default": "all",
          "description": "Deepest heading level shown by default in the outline sidebar. Deeper headings stay reachable by expanding."
        },
        "markdownForHumans.outline.sidebar.width": {
          "type": "string",
          "enum": [
            "default",
            "narrow",
            "medium",
            "wide"
          ],
          "default": "default",
          "description": "Width of the outline sidebar (sidebar mode)."
        }
      }
